mods.body:
html,
body {
  overflow: auto !important;
}
.Modal-wrapper:has(.signFlowModal),
.SignFlowHomepage,
.Question-sideColumnAd,
.Pc-card,
.MCNLinkCard,
.Sticky .RightSideBar,
.AppBanner {
  display: none !important;
}

.Question-main {
  width: min(920px, 92vw) !important;
  margin: 0 auto !important;
}
.Question-mainColumn,
.Post-Main {
  width: 100% !important;
  max-width: 820px !important;
  margin: 0 auto !important;
}
.RichText {
  font-size: 16px !important;
  line-height: 1.8 !important;
}

(() => {
  function unwrapLinks(root) {
    const anchors = (root || document).querySelectorAll('a[href*="link.zhihu.com"]');
    for (const a of anchors) {
      try {
        const u = new URL(a.href);
        const target = u.searchParams.get('target');
        if (target && /^https?:\/\//i.test(target)) {
          a.href = target;
          a.removeAttribute('data-za-detail-view-id');
        }
      } catch {
        /* skip malformed URL */
      }
    }
  }
  unwrapLinks(document);
  const obs = new MutationObserver(() => unwrapLinks(document));
  if (document.body) obs.observe(document.body, { childList: true, subtree: true });
})();

